async function migrateRealArchive(){if(!rootDir)throw Error('Önce AT AI MOBIL klasörünü seçin');let y=Number(m8y.value);if(!y)throw Error('Aktarılacak yılı seçin');let races=await realArchiveYear(y);if(!races.length)throw Error(y+' için Gerçek Yarış Arşivinde kayıt bulunamadı');let groups=new Map();for(const x of races){if(!x.date||!x.city)continue;let k=x.date+'|'+x.city,g=groups.get(k)||{key:k,date:x.date,city:x.city,count:0,races:[]};g.count++;g.races.push(x);groups.set(k,g)}let arr=[...groups.values()],ok=0,skipped=0,deleted=0,err=0;m8sum.textContent=y+' gerçek arşivi · '+arr.length+' gün/şehir kontrol edilecek';for(const g of arr){if(stop)break;try{let existing=await readArchive(g.date,g.city);if(existing){skipped++;let n=await deleteRealArchiveGroup(g);if(n===g.races.length)deleted+=n;else if(n)throw Error('IndexedDB temizleme eksik')}else{await saveFile(g,{ok:true,source:'at_ai_tjk_annual_results_v1',races:g.races});let verify=await readArchive(g.date,g.city);if(!verify||!Array.isArray(verify?.data?.races)||verify.data.races.length!==g.races.length)throw Error('Kalıcı dosya doğrulanamadı');ok++;let n=await deleteRealArchiveGroup(g);if(n===g.races.length)deleted+=n;else if(n)throw Error('IndexedDB temizleme eksik')}}catch(e){err++}m8sum.textContent=y+' aktarım · '+(ok+skipped+err)+'/'+arr.length+' · Yeni '+ok+' · Zaten Var '+skipped+' · IndexedDB’den Silinen '+deleted+' yarış · Hata '+err;await new Promise(q=>setTimeout(q,10))}m8sum.textContent=y+' gerçek arşivi · Yeni '+ok+' · Zaten Var '+skipped+' · IndexedDB’den Silinen '+deleted+' yarış · '+err+' hata';return{ok,skipped,deleted,err}}
async function migrateOld(){if(!rootDir)throw Error('Önce AT AI MOBIL klasörünü seçin');let y=m8y.value,c=m8c.value,a=m8a.value,b=m8b.value,all=await getAll(),src=all.filter(x=>x&&x.data&&x.date&&x.city&&(!y||x.date.startsWith(y))&&(!c||x.city===c)&&(!a||x.date>=a)&&(!b||x.date<=b)),ok=0,err=0;m8sum.textContent='Eski arşiv taranıyor · '+src.length+' kayıt';for(const x of src){if(stop)break;try{let r={key:x.key,date:x.date,city:x.city,count:x.count||0};await saveFile(r,x.data);await del(x.key);ok++}catch(e){err++}m8sum.textContent='Aktarım · '+(ok+err)+'/'+src.length+' · Başarılı '+ok+' · Hata '+err;await new Promise(q=>setTimeout(q,20))}m8sum.textContent='Aktarım tamamlandı · '+ok+' taşındı ve IndexedDB’den silindi · '+err+' hata';return{ok,err}}
