async function saveHorseArchive(horse,remote,existing){let d=await horseArchiveDir(true),old=(existing?.races||existing?.data?.races||[]),fresh=(remote?.races||[]),map=new Map();for(const r of [...old,...fresh])map.set(raceKey(r),r);let races=[...map.values()].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));let doc={version:'AT-HORSE-ARCHIVE-V2',horseId:String(horse.id),name:horse.name||remote?.horse||existing?.name||'',origin:horse.origin||existing?.origin||'',lastUpdated:new Date().toISOString(),lastRaceDate:races[0]?.date||'',races};let fh=await d.getFileHandle(String(horse.id)+'.json',{create:true}),w=await fh.createWritable();await w.write(JSON.stringify(doc,null,2));await w.close();return{doc,added:Math.max(0,races.length-old.length),oldCount:old.length}}
