by('m8tabTrack').onclick=()=>{setTab(2);let y=new Date().getFullYear(),ys=Array.from({length:y-1999},(_,i)=>y-i).map(v=>'<option value="'+v+'">'+v+'</option>').join('');by('m8tool').innerHTML='<h3>Yıllık Pist / Bakım / Hava Arşivi</h3><div class="m8muted">Geçmiş TJK pist raporlarını yıl bazında toplar. Mevcut güvenli pist arşiv motoru kullanılır.</div><button id="m8TrackFolder">📁 Pist Arşivi Klasörünü Seç</button><div class="m8actions" style="margin-top:10px"><label>Başlangıç yılı<select id="m8TrackFrom" style="width:100%;padding:12px;background:#25282b;color:#fff">'+ys+'</select></label><label>Bitiş yılı<select id="m8TrackTo" style="width:100%;padding:12px;background:#25282b;color:#fff">'+ys+'</select></label></div><button id="m8TrackYears" class="m8hot" style="width:100%;margin-top:10px">Geçmiş Yılları Doldur</button><button id="m8TrackToday" style="width:100%;margin-top:8px">Bugüne Kadar Eksikleri Güncelle</button><div id="m8TrackStatus" class="m8muted" style="margin-top:10px">Hazır.</div>';by('m8TrackFolder').onclick=async()=>{let s=by('m8TrackStatus');try{s.textContent='Pist arşivi klasörü seçiliyor…';await chooseDir();s.textContent='✓ Pist arşivi klasörü hazır: '+(rootDir?.name||'Gerçek Yarış Arşivi')}catch(x){s.textContent='⚠ '+x.message}};by('m8TrackFrom').value=String(Math.max(2000,y-5));by('m8TrackTo').value=String(y);by('m8TrackYears').onclick=async()=>{let s=by('m8TrackStatus');try{let a=Number(by('m8TrackFrom').value),b=Number(by('m8TrackTo').value),m=window.ATTrackMaintenanceV1;if(!m?.backfillYears)throw Error('Pist arşiv motoru hazır değil');s.textContent=a+'–'+b+' geçmişi hazırlanıyor…';await m.backfillYears(a,b);s.textContent='✓ '+a+'–'+b+' arşivi tamamlandı.'}catch(x){s.textContent='⚠ '+x.message}};by('m8TrackToday').onclick=async()=>{let s=by('m8TrackStatus');try{let m=window.ATTrackMaintenanceV1;if(!m?.autoSync)throw Error('Pist arşiv motoru hazır değil');s.textContent='Eksikler güncelleniyor…';await m.autoSync(new Date().toISOString().slice(0,10));s.textContent='✓ Bugüne kadar eksikler güncellendi.'}catch(x){s.textContent='⚠ '+x.message}}};
by('m8tabOrigin').onclick=()=>{setTab(3);by('m8tool').innerHTML='<h3>Orijin</h3><div class="m8muted">Programdaki atların baba/anne hattını TJK üzerinden günceller ve yıllık Orijin Arşivine yazar.</div><button id="m8OriginFolder">📁 Arşiv Klasörünü Seç</button><button id="m8OriginRun" class="m8hot" style="margin-left:6px">Program Orijinlerini Güncelle</button><div id="m8OriginStatus" class="m8muted" style="margin-top:10px">Hazır.</div>';by('m8OriginFolder').onclick=async()=>{let s=by('m8OriginStatus');try{await chooseDir();s.textContent='Klasör hazır.'}catch(x){s.textContent='⚠ '+x.message}};by('m8OriginRun').onclick=async()=>{let s=by('m8OriginStatus');s.textContent='Program ve orijinler okunuyor…';await updateFogArchive('O',by('m8ProgramDate').value,s)}};
